/* Compare numeric values
 */
static int
jvp_number_cmp(const jv a, const jv b)
{
  decNumber res;
  memset(&res, 0, sizeof(res));
  if (jv_get_kind(a) == JV_KIND_NUMBER && jv_get_kind(b) == JV_KIND_NUMBER) {
    decContext set;
    decDefaultContext(&set);
    set.trap_enables = 0;
    decNumber *x = jvp_number_get(a);
    decNumber *y = jvp_number_get(b);
    decNumberCompare(&res, x, y, &set);
    int cmp = decNumberGetInt(&res);
    if (cmp > 0) return 1;
    if (cmp < 0) return -1;
    return 0;
  }
  return jv_invalid_get_kind(a) - jv_invalid_get_kind(b);
}

